import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-login-links.json"), "utf8"),
);
const models = emitModels(contract.models, "loginLinkStatusSchema");
const go =
  '// Code generated by scripts/generate-workforce-login-links.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
const ts =
  '// Generated by scripts/generate-workforce-login-links.mjs.\nimport { z } from "zod";\n\n' +
  `export const LOGIN_LINK_STATUSES=${JSON.stringify(contract.statuses)} as const;\nexport const loginLinkStatusSchema=z.enum(${JSON.stringify(Object.keys(contract.statuses))});\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/login_link_types.go",
  go + models.go,
  "packages/api/src/login-link-contract.ts",
  ts + models.ts,
  "staff login links",
);
